// --- PRNG (fast, seedable; tests use a fixed seed for stability) --------------------------------

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a += 0x6d2b79f5;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createRebuildRng(): () => number {
  if (typeof process !== 'undefined' && process.env.NODE_ENV === 'test') {
    return mulberry32(0x9e3779b9);
  }
  const s = (Math.floor(Math.random() * 0xffffffff) ^ Date.now()) >>> 0;
  return mulberry32(s === 0 ? 0xfeedface : s);
}

function pick<T>(arr: readonly T[], rng: () => number): T {
  return arr[Math.min(arr.length - 1, Math.floor(rng() * arr.length))]!;
}

function clamp01(x: number): number {
  return Math.min(1, Math.max(0, x));
}

