type SimDay = {
  dateKey: string;
  mood: MoodGrade;
  note: string;
  latent: number;
  createdAt: number;
  updatedAt: number;
};

type LifeSim = {
  latent: number;
  momentum: number;
  spikeKind: 'none' | 'up' | 'down';
  spikeLabel: string;
  spikeAge: number;
};

function initLifeSim(rng: () => number): LifeSim {
  return {
    latent: 0.45 + rng() * 0.22,
    momentum: (rng() - 0.5) * 0.2,
    spikeKind: 'none',
    spikeLabel: '',
    spikeAge: 999,
  };
}

function advanceLifeSim(sim: LifeSim, dateKey: string, rng: () => number): void {
  const y = Number(dateKey.slice(0, 4));

  sim.latent += (0.52 - sim.latent) * (0.018 + rng() * 0.022);
  sim.momentum *= 0.82;
  sim.momentum += (rng() - 0.5) * 0.095;
  sim.latent += sim.momentum * 0.055;

  if (y <= 2021 && rng() < 0.07) sim.latent -= 0.028 + rng() * 0.04;
  if (y >= 2022 && y <= 2023 && rng() < 0.045) sim.latent -= 0.015;

  if (rng() < 0.017) {
    sim.spikeKind = rng() < 0.48 ? 'down' : 'up';
    sim.spikeLabel = pick(sim.spikeKind === 'down' ? BAD_SPIKES : GOOD_SPIKES, rng);
    sim.latent += sim.spikeKind === 'down' ? -(0.12 + rng() * 0.2) : 0.08 + rng() * 0.16;
    sim.spikeAge = 0;
  } else {
    sim.spikeAge += 1;
  }

  if (rng() < 0.006) sim.momentum += (rng() - 0.5) * 0.45;

  sim.latent = clamp01(sim.latent);
}

function latentToMood(sim: LifeSim, rng: () => number): MoodGrade {
  const noise = (rng() - 0.5) * 0.13;
  const x = clamp01(sim.latent + noise + sim.momentum * 0.12);
  if (x >= 0.86) return rng() < 0.38 ? 'A+' : 'A';
  if (x >= 0.68) return rng() < 0.72 ? 'A' : 'B';
  if (x >= 0.48) return rng() < 0.55 ? 'B' : 'C';
  if (x >= 0.28) return rng() < 0.62 ? 'C' : 'D';
  return rng() < 0.55 ? 'D' : 'F';
}

function shuffle<T>(arr: readonly T[], rng: () => number): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const t = a[i]!;
    a[i] = a[j]!;
    a[j] = t;
  }
  return a;
}

function eraFragments(dateKey: string, rng: () => number): string[] {
  const y = Number(dateKey.slice(0, 4));
  const out: string[] = [];
  if (y <= 2021 && rng() < 0.34) out.push(pick(ERA_2020_2021, rng));
  else if (y >= 2022 && y <= 2023 && rng() < 0.28) out.push(pick(ERA_2022_2023, rng));
  else if (y >= 2024 && rng() < 0.26) out.push(pick(ERA_2024_PLUS, rng));
  return out;
}

function buildLifeNote(dateKey: string, mood: MoodGrade, sim: LifeSim, rng: () => number): string {
  if (rng() < 0.1) {
    const micro =
      mood === 'A+' || mood === 'A'
        ? pick(['Good day.', 'Light.', 'Okay.'], rng)
        : mood === 'B'
          ? pick(['Meh but fine.', 'Nothing special.', 'Logging anyway.'], rng)
          : pick(['Rough day.', 'Low bandwidth.', 'Honest entry.'], rng);
    return normalizeNote(micro).slice(0, 200);
  }

  const parts: string[] = [];

  if (sim.spikeAge <= 4 && sim.spikeKind !== 'none' && rng() < 0.72) {
    parts.push(sim.spikeLabel);
  }

  parts.push(...eraFragments(dateKey, rng));

  if (mood === 'A+' || mood === 'A') {
    parts.push(pick(MUNDANE_GOOD, rng));
    if (rng() < 0.45) parts.push(pick(CLOSERS_UP, rng));
  } else if (mood === 'B') {
    parts.push(pick(MUNDANE_NEUTRAL, rng));
    if (rng() < 0.35) parts.push(pick(MUNDANE_GOOD, rng));
  } else if (mood === 'C') {
    parts.push(pick(MUNDANE_NEUTRAL, rng));
    if (rng() < 0.4) parts.push(pick(MUNDANE_HARD, rng));
  } else {
    parts.push(pick(MUNDANE_HARD, rng));
    if (rng() < 0.55) parts.push(pick(BAD_SPIKES, rng));
    if (rng() < 0.4) parts.push(pick(CLOSERS_DOWN, rng));
  }

  const raw = parts.filter(Boolean).join(' ');
  return normalizeNote(raw).slice(0, 200);
}

function simulateLifeDays(allKeys: readonly string[], rng: () => number): SimDay[] {
  const sim = initLifeSim(rng);
  const out: SimDay[] = [];

  for (const dateKey of allKeys) {
    advanceLifeSim(sim, dateKey, rng);
    const mood = latentToMood(sim, rng);
    const note = buildLifeNote(dateKey, mood, sim, rng);

    const [y, m, d] = dateKey.split('-').map(Number);
    const baseHour = mood === 'F' || mood === 'D' ? 1 + Math.floor(rng() * 3) : 9 + Math.floor(rng() * 8);
    const baseMin = Math.floor(rng() * 60);
    const base = new Date(y!, m! - 1, d!, baseHour, baseMin, Math.floor(rng() * 60)).getTime();
    const updatedAt = base + Math.floor(rng() * (mood === 'A+' || mood === 'A' ? 6 : 10) * 60 * 60 * 1000);

    out.push({ dateKey, mood, note, latent: sim.latent, createdAt: base, updatedAt });
  }
  return out;
}

