function buildDayTodos(ctx: SimDay, rng: () => number): DayTodoItem[] | null {
  if (rng() > 0.48) return null;
  const n = rng() < 0.34 ? 2 : 1;
  const items: DayTodoItem[] = [];
  const pools: (readonly string[])[] = [];
  if (ctx.latent < 0.42) pools.push(TODO_CARE, TODO_LIFE_ADMIN);
  else pools.push(TODO_WORK, TODO_CARE, TODO_SOCIAL, TODO_LIFE_ADMIN);

  const REMINDER_MINUTES_POOL = [
    7 * 60 + 10 + Math.floor(rng() * 40),
    8 * 60 + 20 + Math.floor(rng() * 50),
    9 * 60 + Math.floor(rng() * 45),
    12 * 60 + 5 + Math.floor(rng() * 55),
    16 * 60 + 40 + Math.floor(rng() * 50),
    18 * 60 + 30 + Math.floor(rng() * 40),
    20 * 60 + 15 + Math.floor(rng() * 35),
  ];

  for (let i = 0; i < n; i++) {
    const pool = pick(pools, rng);
    const withRem = rng() < 0.55;
    items.push({
      id: `seed-todo-${ctx.dateKey}-${i}`,
      title: pick(pool, rng),
      done: rng() < 0.3,
      createdAt: ctx.createdAt + i * 1000,
      sortIndex: i,
      reminderMinutes: withRem ? pick(REMINDER_MINUTES_POOL, rng) : null,
    });
  }
  return items;
}

function buildHabitDay(ctx: SimDay, rng: () => number): HabitId[] | null {
  if (ctx.mood === 'F' && rng() < 0.55) return null;
  if (rng() > 0.55) return null;
  const k = 1 + Math.floor(rng() * 3);
  const pool = shuffle(HABIT_IDS, rng);
  return pool.slice(0, k) as HabitId[];
}

// --- Goals + history ----------------------------------------------------------------------------

function listLocalDayKeys(fromKey: string, toKey: string): string[] {
  const out: string[] = [];
  let cur = parseISODate(fromKey);
  const end = parseISODate(toKey);
  if (!Number.isFinite(cur.getTime()) || !Number.isFinite(end.getTime())) return out;
  while (cur.getTime() <= end.getTime()) {
    out.push(formatDateToISO(cur));
    cur = new Date(cur.getFullYear(), cur.getMonth(), cur.getDate() + 1);
  }
  return out;
}

function randomHistoryForHabit(
  goalId: string,
  fromKey: string,
  toKey: string,
  hitRate: number,
  noteChance: number,
  rng: () => number
): GoalHistory[] {
  const out: GoalHistory[] = [];
  for (const date of listLocalDayKeys(fromKey, toKey)) {
    if (rng() > hitRate) continue;
    const value = rng() < 0.9 ? 1 : 0;
    const note =
      value > 0 && rng() < noteChance
        ? normalizeNote(
            pick(
              [
                'Quick log after the reminder.',
                'Did the minimum and it helped.',
                'Almost skipped — glad I did not.',
                'Busy day but squeezed it in.',
                'Partner joined me today — easier.',
              ],
              rng
            )
          ).slice(0, 120)
        : '';
    const [y, m, d] = date.split('-').map(Number);
    const hourJitter = Math.floor(rng() * 4);
    const minJitter = Math.floor(rng() * 60);
    const createdAt = new Date(y!, m! - 1, d!, 8 + hourJitter, minJitter).getTime();
    out.push({
      id: `${goalId}:h:${date}`,
      date,
      value,
      note,
      createdAt,
    });
  }
  return out.slice(-800);
}

function sleepHoursHistory(goalId: string, fromKey: string, toKey: string, rng: () => number): GoalHistory[] {
  const out: GoalHistory[] = [];
  for (const date of listLocalDayKeys(fromKey, toKey)) {
    if (rng() > 0.76) continue;
    const clusterBad = rng() < 0.14;
    const hours = clusterBad ? 5.1 + rng() * 1.4 : 6.4 + rng() * 1.9;
    const value = Math.round(hours * 10) / 10;
    const [y, m, d] = date.split('-').map(Number);
    const createdAt = new Date(y!, m! - 1, d!, 9, 7 + Math.floor(rng() * 20)).getTime();
    out.push({
      id: `${goalId}:s:${date}`,
      date,
      value,
      note: rng() < 0.22 ? pick(['Wind-down alarm set.', 'Melatonin + no reels.', 'Slept on the couch by accident.'], rng) : '',
      createdAt,
    });
  }
  return out.slice(-900);
}

